import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";

type Todo = { id: number; title: string; done: boolean };

export function useTodos(filter: "all" | "open") {
  return useQuery({
    queryKey: ["todos", { filter }],          // всё, от чего зависит запрос, лежит в ключе
    queryFn: async ({ signal }) => {
      const res = await fetch("/api/todos?filter=" + filter, { signal });
      if (!res.ok) throw new Error(res.statusText);
      return (await res.json()) as Todo[];
    },
    staleTime: 30_000, // 30 с данные свежие: монтирование и фокус окна не вызовут refetch
  });
}

export function useToggleTodo() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (id: number) => fetch("/api/todos/" + id + "/toggle", { method: "POST" }),

    onMutate: async (id) => {
      // 1. остановить летящие refetch этого ключа, иначе их ответ перезапишет нас
      await queryClient.cancelQueries({ queryKey: ["todos"] });
      // 2. снимок того, что сейчас в кеше
      const previous = queryClient.getQueriesData<Todo[]>({ queryKey: ["todos"] });
      // 3. записать оптимистичную версию во все подходящие записи кеша
      queryClient.setQueriesData<Todo[]>({ queryKey: ["todos"] }, (old) =>
        old?.map((t) => (t.id === id ? { ...t, done: !t.done } : t)),
      );
      // 4. отдать снимок в onError / onSettled
      return { previous };
    },

    onError: (_err, _id, context) => {
      // 5. вернуть снимок на место
      context?.previous.forEach(([key, data]) => queryClient.setQueryData(key, data));
    },

    onSettled: () => {
      // 6. успех или ошибка: последнее слово за сервером. Промис возвращаем,
      //    чтобы мутация оставалась pending, пока идёт refetch
      return queryClient.invalidateQueries({ queryKey: ["todos"] });
    },
  });
}

"use client";
import { useRouter, usePathname, useSearchParams } from "next/navigation";

export function SortSelect() {
  const router = useRouter();
  const pathname = usePathname();
  const searchParams = useSearchParams();        // URLSearchParams только для чтения
  const sort = searchParams.get("sort") ?? "new"; // источник правды — адрес

  function setSort(next: string) {
    const params = new URLSearchParams(searchParams.toString());
    params.set("sort", next);
    router.replace(pathname + "?" + params.toString()); // replace: без новой записи в истории
  }

  return (
    <select value={sort} onChange={(e) => setSort(e.target.value)}>
      <option value="new">Newest</option>
      <option value="top">Top</option>
    </select>
  );
}

