import { create } from "zustand";
import { useShallow } from "zustand/react/shallow";

const useComposer = create<{ draft: string; files: string[]; theme: "light" | "dark" }>(() => ({
  draft: "", files: [], theme: "dark",
}));

// перерисуется только при смене theme
const theme = useComposer((s) => s.theme);

// ЛОВУШКА: filter создаёт новый массив при каждом вызове, значит рендер на любое изменение стора
const pdfs = useComposer((s) => s.files.filter((f) => f.endsWith(".pdf")));

// починка: сравнивать содержимое, а не ссылку
const pdfsOk = useComposer(useShallow((s) => s.files.filter((f) => f.endsWith(".pdf"))));

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";

type Todo = { id: number; title: string; done: boolean };

export function useTodos(filter: "all" | "open") {
  return useQuery({
    queryKey: ["todos", { filter }],          // everything the fetch depends on goes into the key
    queryFn: async ({ signal }) => {
      const res = await fetch("/api/todos?filter=" + filter, { signal });
      if (!res.ok) throw new Error(res.statusText);
      return (await res.json()) as Todo[];
    },
    staleTime: 30_000, // fresh for 30 s: mount and window focus won't refetch
  });
}

export function useToggleTodo() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (id: number) => fetch("/api/todos/" + id + "/toggle", { method: "POST" }),

    onMutate: async (id) => {
      // 1. stop in-flight refetches of this key, or their response overwrites us
      await queryClient.cancelQueries({ queryKey: ["todos"] });
      // 2. snapshot what the cache holds right now
      const previous = queryClient.getQueriesData<Todo[]>({ queryKey: ["todos"] });
      // 3. write the optimistic version into every matching cache entry
      queryClient.setQueriesData<Todo[]>({ queryKey: ["todos"] }, (old) =>
        old?.map((t) => (t.id === id ? { ...t, done: !t.done } : t)),
      );
      // 4. hand the snapshot to onError / onSettled
      return { previous };
    },

    onError: (_err, _id, context) => {
      // 5. put the snapshot back
      context?.previous.forEach(([key, data]) => queryClient.setQueryData(key, data));
    },

    onSettled: () => {
      // 6. success or failure: the server has the last word. Return the promise
      //    so the mutation stays pending until the refetch is done
      return queryClient.invalidateQueries({ queryKey: ["todos"] });
    },
  });
}

